class Solution {
  public int[] hitBricks(int[][] grid, int[][] hits) {
    int m = grid.length, n = grid[0].length;
    boolean[][] removed = new boolean[m][n];
    for (int[] hit : hits)
      if (grid[hit[0]][hit[1]] == 1) {
        grid[hit[0]][hit[1]] = 0;
        removed[hit[0]][hit[1]] = true;
      }
    int[][] copy = new int[m][n];
    for (int i = 0; i < m; i++) copy[i] = grid[i].clone();
    DisjointSet dsu = new DisjointSet(m * n + 1);
    int roof = m * n;
    for (int r = 0; r < m; r++)
      for (int c = 0; c < n; c++)
        if (copy[r][c] == 1) {
          int id = r * n + c;
          if (r == 0) dsu.union(id, roof);
          if (r > 0 && copy[r - 1][c] == 1) dsu.union(id, id - n);
          if (c > 0 && copy[r][c - 1] == 1) dsu.union(id, id - 1);
        }
    int[] result = new int[hits.length];
    for (int h = hits.length - 1; h >= 0; h--) {
      int r = hits[h][0], c = hits[h][1];
      if (!removed[r][c]) continue;
      int before = dsu.size[dsu.find(roof)];
      copy[r][c] = 1;
      int id = r * n + c;
      if (r == 0) dsu.union(id, roof);
      for (int[] d : DIR) {
        int nr = r + d[0], nc = c + d[1];
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) dsu.union(id, nr * n + nc);
      }
      int after = dsu.size[dsu.find(roof)];
      result[h] = Math.max(0, after - before - 1);
    }
    return result;
  }

  private static final int[][] DIR = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

  private static class DisjointSet {
    int[] parent, size;

    DisjointSet(int n) {
      parent = new int[n];
      size = new int[n];
      for (int i = 0; i < n; i++) {
        parent[i] = i;
        size[i] = 1;
      }
    }

    int find(int x) {
      while (x != parent[x]) {
        parent[x] = parent[parent[x]];
        x = parent[x];
      }
      return x;
    }

    void union(int a, int b) {
      int ra = find(a), rb = find(b);
      if (ra == rb) return;
      if (size[ra] < size[rb]) {
        int t = ra;
        ra = rb;
        rb = t;
      }
      parent[rb] = ra;
      size[ra] += size[rb];
    }
  }
}
